import json
from pathlib import Path
p=Path(__file__).parent
cases=[]
def add(name,sql,batch=3):cases.append({'id':name,'sql':sql,'batch_size':batch})
def typed(v,t):return f"CAST({repr(v) if v is not None else 'NULL'} AS {t})"
for ft in ['FLOAT','DOUBLE']:
 tag=ft.lower()
 vals=['-0.0','0.0','0.1','2.5','-2.5','NaN','Infinity','-Infinity','1e-40','-1e-40',None]
 table='VALUES '+','.join(f'({i},{typed(v,ft)})' for i,v in enumerate(vals))+ ' t(id,v)'
 lists={'short':'0.0,0.1,2.5','null':'0.0,0.1,2.5,NULL','nan':f"0.0,CAST('NaN' AS {ft}),2.5",'signed_nan':f"0.0,-CAST('NaN' AS {ft}),2.5,NULL",'infinity':f"CAST('Infinity' AS {ft}),-1.0,CAST('-Infinity' AS {ft})",'single':'0.0','long':','.join(['0.0','0.1','2.5']+[f'{i}.125' for i in range(128)])}
 for name,items in lists.items():
  for op,label in [('IN','in'),('NOT IN','not_in')]:
   add(f'{tag}_{name}_{label}',f'SELECT id,CAST(v {op} ({items}) AS INT) q FROM {table} ORDER BY id')
 add(f'{tag}_filter',f'SELECT id FROM {table} WHERE v IN (0.0,0.1,2.5) ORDER BY id')
 add(f'{tag}_case',f'SELECT id,CASE WHEN v IN (0.0,0.1,2.5,NULL) THEN 1 WHEN v NOT IN (0.0,0.1,2.5,NULL) THEN 0 ELSE -1 END q FROM {table} ORDER BY id')
 add(f'{tag}_count',f'SELECT count(*) q FROM {table} WHERE v NOT IN (0.0,0.1,2.5)')
 pairs=[('-0.0','0','1'),('0.1','0.1','0.5'),('2.5','3','2.5'),('NaN','0','NaN'),('Infinity','0','Infinity'),('-Infinity','1','-Infinity'),('1.25',None,None),(None,'0','NaN')]
 table='VALUES '+','.join(f'({i},{typed(v,ft)},{typed(d,"DECIMAL(38,18)")},{typed(g,ft)})' for i,(v,d,g) in enumerate(pairs))+' t(id,v,d,g)'
 for left,right in [('v','d,g'),('d','v,g'),('v','g,d'),('d','g,v')]:
  for op,label in [('IN','in'),('NOT IN','not_in')]:add(f'{tag}_columns_{left}_{right.replace(",", "_")}_{label}',f'SELECT id,CAST({left} {op} ({right}) AS INT) q FROM {table} ORDER BY id')
 add(f'{tag}_scalar_subquery',f'SELECT id,CAST(v IN (d,(SELECT {typed("NaN",ft)})) AS INT) q FROM {table} ORDER BY id')
 for value in ['-0.0','NaN','2.5',None]:
  name=str(value).replace('-','negative_').replace('.','_')
  add(f'{tag}_scalar_{name}',f'SELECT CAST({typed(value,ft)} IN (0.0,2.5,CAST(\'NaN\' AS {ft}),NULL) AS INT) q')
 for dt,dvalues in [('DECIMAL(10,7)',['0','0.1','2.5','-2.5',None]),('DECIMAL(38,18)',['9007199254740993','-9007199254740993','0.100000000000000001','0',None])]:
  table='VALUES '+','.join(f'({i},{typed(v,dt)})' for i,v in enumerate(dvalues))+' t(id,v)'
  items=f"{typed('9007199254740992',ft)},{typed('-9007199254740992',ft)},{typed('0.1',ft)},{typed('2.5',ft)},{typed('-0.0',ft)},NULL"
  for op,label in [('IN','in'),('NOT IN','not_in')]:add(f'{tag}_{"wide" if "38" in dt else "narrow"}_decimal_{label}',f'SELECT id,CAST(v {op} ({items}) AS INT) q FROM {table} ORDER BY id')
for left in ["CAST(9007199254740993 AS BIGINT)","CAST(NULL AS BIGINT)","NULL"]:
 add(f'whole_list_{len(cases)}',f'SELECT CAST({left} IN (CAST(9007199254741001 AS DECIMAL(38,0)),CAST(9007199254740992 AS DOUBLE),NULL) AS INT) q')
for name,t,items in [('integer','BIGINT','0,2,3,NULL'),('decimal','DECIMAL(18,4)','0.0,2.0,3.0,NULL'),('double','DOUBLE',"CAST(0 AS DOUBLE),CAST(2 AS DOUBLE),NULL"),('string','STRING',"'0','2',NULL")]:
 table='VALUES '+','.join(f'({i},{typed(v,t)})' for i,v in enumerate(['0','1','2',None]))+' t(id,v)'
 for op,label in [('IN','in'),('NOT IN','not_in')]:add(f'control_{name}_{label}',f'SELECT id,CAST(v {op} ({items}) AS INT) q FROM {table} ORDER BY id')
case=next(x for x in cases if x['id']=='double_signed_nan_not_in')
for batch in [1,64]:add(f'double_signed_nan_batch{batch}',case['sql'],batch)
assert len({x['id'] for x in cases})==len(cases)
(p/'cases.jsonl').write_text(''.join(json.dumps(x)+'\n' for x in cases))
print(len(cases),'queries',len(cases)*2,'observations')

